'use strict';
let rankingEpoch=0;
function installOfficialRanking(){
 const local=rankingRoom,PARTICIPANTS=KEY+'-online-participants-v14',RUNS=KEY+'-official-runs-v14';
 let official=null,pending=null,working=false,deferred=false,visit=0;
 const departments={pref:'都道府県10問・4択',location:'都道府県の位置10問・地図タップ',capital:'県庁所在地10問・4択',terrain:'地形10問・発展（入門・基本を含む）・4択',mixed:'総合10問・発展（入門・基本を含む）・4択'};
 const read=key=>{const raw=localStorage.getItem(key);if(!raw)return {};try{const m=JSON.parse(raw);if(!m||typeof m!=='object'||Array.isArray(m))throw Error();return m}catch{throw Error('オンライン参加情報を読み込めません。先生に相談してください。')}};
 const context=()=>({id:player().id,epoch:rankingEpoch});
 const valid=c=>registeredAccess()&&player().id===c.id&&rankingEpoch===c.epoch;
 const guard=c=>{if(!valid(c))throw Error('本人確認が変わりました。本人の名前で入り直してください。')};
 function credential(c){guard(c);return read(PARTICIPANTS)[c.id]||null;}
 async function api(action,body,c=null,key=null){
  if(body){if(!c)throw Error('登録した本人で入ってください。');guard(c)}
  const cred=key||(c&&valid(c)?credential(c):null),headers={...(body?{'Content-Type':'application/json'}:{}),...(cred?{'X-JG-Player':cred.id,'X-JG-Key':cred.key}:{})};
  const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),20000);let r;try{r=await fetch('/api/rank/'+action,{signal:controller.signal,method:body?'POST':'GET',credentials:'same-origin',headers,body:body?JSON.stringify(body):undefined,cache:'no-store'});}catch{throw Error('通信できません。もう一度お試しください。')}finally{clearTimeout(timeout)}let j;
  try{j=await r.json()}catch{throw Error('通信できません。端末内の学習は続けられます。')}
  if(c)guard(c);if(!r.ok){const e=Error(j.error||'通信に失敗しました');e.status=r.status;throw e}return j;
 }
 async function ensure(c){guard(c);await api('identity',{},c);let cred=credential(c);if(!cred){cred=await api('participant',{},c);guard(c);const m=read(PARTICIPANTS);m[c.id]=cred;localStorage.setItem(PARTICIPANTS,JSON.stringify(m));}await api('profile',{nickname:player().name},c,cred);return cred;}
 const tabs=active=>`<div class="rankingTabs" role="tablist" aria-label="ランキングの種類"><button id="localRank" role="tab" aria-selected="${active==='local'}">自己ベスト</button><button id="onlineRank" role="tab" aria-selected="${active==='online'}">オンラインランキング</button></div>`;
 const bindTabs=()=>{$('#localRank').onclick=()=>navigate(rankingRoom);$('#onlineRank').onclick=()=>navigate(onlineHub)};
 rankingRoom=()=>{visit++;local();app.insertAdjacentHTML('afterbegin',tabs('local'));bindTabs();};
 function remember(run=official){const m=read(RUNS);m[run.localPlayer]=run;localStorage.setItem(RUNS,JSON.stringify(m));}
 function forget(id){const m=read(RUNS);delete m[id];localStorage.setItem(RUNS,JSON.stringify(m));try{const old=JSON.parse(sessionStorage.getItem('japan-geography-official-v13'));if(old?.localPlayer===id)sessionStorage.removeItem('japan-geography-official-v13')}catch{}}
 function savedRun(){if(!registeredAccess())return null;const s=read(RUNS)[player().id];if(s&&(s.version==='japan-geography-official-v14-players'||s.legacy)&&s.expires>Date.now()&&!s.done)return s;try{const old=JSON.parse(sessionStorage.getItem('japan-geography-official-v13'));if(old?.localPlayer===player().id&&old.version==='japan-geography-official-v13'&&!old.done)return {...old,legacy:true};}catch{}return null;}

 function onlineHub(){
  view='rankings';const v=++visit;document.body.classList.remove('quiz','responded');game=null;
  app.innerHTML=`${back()}${tabs('online')}<h1>オンラインランキング</h1>${registeredAccess()?`<p>${esc(player().icon)} ${esc(player().name)} で参加します。</p>`:'<p class="notice">ゲストは見るだけです。挑戦するときは自分の名前で入ってね。</p>'}<p class="note">10問・ヒントなし。通常テストの成績には含みません。</p><label for="officialDept">部門</label><select id="officialDept">${Object.entries(departments).map(([id,n])=>`<option value="${id}">${n}</option>`).join('')}</select><div class="row"><button id="officialStart" class="primary" ${registeredAccess()?'':'disabled'}>公式挑戦を始める</button><button id="officialResume" hidden>挑戦のつづきから</button><button id="reloadBoard">順位を更新</button></div><p id="officialNotice" role="status"></p><div id="onlineBoard"></div><details><summary>ルール・参加情報について</summary><p>制限は開始から1時間。同点は同順位、同点内は達成した順です。児童ごと・部門ごとに自己ベスト1件を掲載します。</p><p>ニックネーム・回答・挑戦時刻をサーバーに送ります。名前を変えた後はここを開くと反映します。端末内のプレイヤーを削除しても掲載済み記録は残ります。</p><p>参加はこの端末とブラウザで継続します。別端末への連携・参加情報の復旧は未対応です。学習バックアップから追加した人は新しい参加者になります。</p><button id="legacyBoard">旧方式のランキングを見る</button></details>`;
  bindBack();bindTabs();$('#officialStart').onclick=begin;$('#officialResume').onclick=resume;$('#reloadBoard').onclick=()=>board(false);$('#officialDept').onchange=()=>board(false);$('#legacyBoard').onclick=()=>board(true);
  if(registeredAccess()){
   const c=context();(async()=>{try{const cred=credential(c);if(cred){await api('profile',{nickname:player().name},c);if(visit===v)board(false);}if(visit!==v)return;const saved=savedRun();if(saved){if(saved.legacy)await ensure(c);const info=await api(saved.legacy?'legacy-resume':'resume',{run:saved.run},c);if(visit===v&&valid(c)){$('#officialResume').hidden=false;if(info.done)$('#officialResume').textContent='結果を確認する';else if(saved.legacy)$('#officialResume').textContent='旧方式の挑戦を続ける';}}}catch(e){if(visit===v&&$('#officialNotice'))$('#officialNotice').textContent=e.message;}})();
  }board(false);
 }
 async function board(legacy=false){const v=visit,dept=$('#officialDept').value,c=registeredAccess()?context():null;$('#onlineBoard').textContent='順位を読み込んでいます…';try{const j=await api((legacy?'legacy':'leaderboard')+'?department='+encodeURIComponent(dept),null,c);if(v!==visit||!$('#onlineBoard')||$('#officialDept').value!==dept)return;$('#onlineBoard').innerHTML=(legacy?'<h2>旧方式の記録</h2><p>ブラウザ単位の過去記録です。児童別の順位には含めません。</p>':'<h2>児童別ランキング</h2>')+(j.rows.length?j.rows.map(r=>`<p class="card">${r.rank}位 ${esc(r.nickname)}${r.mine?'（自分）':''}：${r.right} / ${r.count}問</p>`).join(''):'<p>まだ記録がありません。</p>');}catch(e){if(v===visit&&$('#officialNotice')){$('#officialNotice').textContent=e.message;$('#onlineBoard').textContent='順位を取得できませんでした。「順位を更新」で再試行できます。';}}}
 async function begin(){if(working||!registeredAccess())return;const existing=savedRun();if(existing){modal('<h2>続きの挑戦があります</h2><p>新しく始めると、前の挑戦にはこの画面から戻れなくなります。</p><button id="keepOfficial" class="primary">続きから</button><button id="newOfficial">新しく始める</button>');$('#keepOfficial').onclick=()=>{$('#modal').close();resume()};$('#newOfficial').onclick=()=>{$('#modal').close();beginNew()};return;}return beginNew();}
 async function beginNew(){if(working||!registeredAccess())return;working=true;const c=context(),v=visit,department=$('#officialDept').value;$('#officialStart').disabled=true;$('#officialNotice').textContent='挑戦を準備しています…';try{await ensure(c);const j=await api('start',{department,nickname:player().name},c);official={...j,localPlayer:c.id};pending=null;remember();if(v===visit&&view==='rankings')renderOfficial();}catch(e){if(valid(c)&&v===visit&&$('#officialNotice'))$('#officialNotice').textContent=e.message;}finally{working=false;if($('#officialStart'))$('#officialStart').disabled=!registeredAccess();}}
 async function resume(){if(working||!registeredAccess())return;const c=context(),v=visit;working=true;try{const s=savedRun();if(!s)throw Error('再開できる挑戦はありません。');$('#officialNotice').textContent='続きの問題を確認しています…';if(s.legacy)await ensure(c);const j=await api(s.legacy?'legacy-resume':'resume',{run:s.run},c);official={...s,...j};pending=s.pending||null;official.pending=pending;if(j.done){forget(c.id);if(v===visit)showResult(j);return;}remember();if(v===visit){renderOfficial();working=false;if(pending)await sendPending();}}catch(e){if(valid(c)&&v===visit&&$('#officialNotice')){$('#officialNotice').textContent=e.message;if(e.status===404||e.status===410)$('#officialResume').hidden=true;}}finally{working=false;}}
 afterPlayerUnlock=()=>{if(deferred){deferred=false;if(view!=='official'||official?.localPlayer!==player().id)return;const saved=savedRun();if(saved){official=saved;pending=saved.pending||null;renderOfficial()}}};
 function renderOfficial(){if(!official||official.localPlayer!==player().id)return;if(!registeredAccess()){deferred=true;return;}visit++;view='official';document.body.classList.add('quiz');document.body.classList.remove('responded');$('#appUpdateNotice')?.remove();const sq=official.question,q=data.find(q=>q.id===sq.item);game={options:{mode:'test10',official:true,format:sq.mode==='tap'?'tap':'name'},selected:null};app.innerHTML=`${back()}<div class="row between"><span>公式挑戦</span><span>${official.position+1} / 10問</span></div><div class="progress"><i style="width:${official.position*10}%"></i></div><div class="gameLayout"><div class="mapbox">${mapMarkup('quiz',q)}<div class="mapTools"><button id="zoomIn" aria-label="拡大">＋</button><button id="zoomOut" aria-label="縮小">−</button><button id="resetMap">日本全体</button><button id="focusMap">出題地域</button></div></div><section class="question"><h2 id="prompt">${esc(sq.prompt)}</h2><div id="officialChoices" class="choices">${sq.mode==='tap'?'<p id="selection">地図から選んでください</p><button id="confirmTap" disabled>この場所で回答</button>':sq.options.map(o=>`<button data-official-choice="${o.id}">${esc(o.label)}</button>`).join('')}</div><button id="officialSkip">わからない</button><p id="officialStatus" role="status"></p><button id="officialRetry" hidden>同じ回答を再送する</button></section></div>`;bindBack();bindMap(q);document.querySelectorAll('[data-official-choice]').forEach(b=>b.onclick=()=>submit(b.dataset.officialChoice));$('#confirmTap')?.addEventListener('click',()=>{if(game.selected)submit(game.selected)});$('#officialSkip').onclick=()=>submit('skip');$('#officialRetry').onclick=()=>sendPending();if(pending){$('#officialChoices').querySelectorAll('button').forEach(b=>b.disabled=true);$('#officialSkip').disabled=true;$('#officialRetry').hidden=false;$('#officialStatus').textContent='前の回答を再送してください。';}}
 function showResult(result){view='results';if(game)game.done=true;document.body.classList.remove('quiz');app.innerHTML=`${back()}<h1>公式挑戦の結果</h1>${official?.legacy?'<p>旧方式のランキングに保存しました。</p>':''}<p>${result.right} / ${result.count}問正解</p><button id="officialBoard">オンライン順位を見る</button>`;bindBack();$('#officialBoard').onclick=()=>navigate(onlineHub);}
 async function submit(choice){if(working||pending||!registeredAccess()||official.localPlayer!==player().id)return;pending={run:official.run,position:official.position,question:official.question.id,choice};await sendPending();}
 async function sendPending(){if(working||!pending||!registeredAccess()||official?.localPlayer!==player().id)return;working=true;const c=context(),sent=pending,run=official;try{run.pending=sent;remember(run);$('#officialChoices')?.querySelectorAll('button').forEach(b=>b.disabled=true);if($('#officialSkip'))$('#officialSkip').disabled=true;if($('#officialRetry'))$('#officialRetry').hidden=true;if($('#officialStatus'))$('#officialStatus').textContent='回答を送っています…';const result=await api(run.legacy?'legacy-answer':'answer',sent,c);pending=null;delete run.pending;official={...run,...result};if(result.done){forget(c.id);if(view!=='official')return;showResult(result);}else{remember();if(view==='official')renderOfficial();}}catch(e){if(valid(c)&&view==='official'){if($('#officialStatus'))$('#officialStatus').textContent=e.message;if($('#officialRetry'))$('#officialRetry').hidden=false;}else deferred=true;}finally{working=false;}}
}
